import { View, Text, Pressable, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [tab, setTab] = useState("Профайл");
  const [note, setNote] = useState("");

  return (
    <View style={styles.container}>
      <View style={styles.bodyWrap}>
        {tab === "Сагс" ? (
          <Text nativeID="sbody" style={styles.h}>Сагс</Text>
        ) : (
          <View style={styles.pad}>
            <Text style={styles.h}>Профайл</Text>
            {/* энд бичнэ үү: input-г note төлөвт холбо (value + onChangeText) */}
            <TextInput nativeID="note" style={styles.input} placeholder="Тэмдэглэл" />
          </View>
        )}
      </View>
      <View style={styles.tabbar}>
        {["Нүүр", "Сагс", "Профайл"].map((t, i) => (
          <Pressable key={t} nativeID={"tab" + i} style={styles.tab} onPress={() => setTab(t)}>
            <Text style={styles.tabText}>{t}</Text>
          </Pressable>
        ))}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  bodyWrap: { flex: 1 },
  pad: { flex: 1, padding: 24, gap: 14, justifyContent: "center" },
  h: { fontSize: 20, fontWeight: "bold" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 12 },
  tabbar: { flexDirection: "row", borderTopWidth: 1, borderTopColor: "#e5e7eb" },
  tab: { flexGrow: 1, paddingVertical: 12, alignItems: "center" },
  tabText: { fontWeight: "600", color: "#334155" },
});

registerRootComponent(App);

import { View, Text, Pressable, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [tab, setTab] = useState("Профайл");
  const [note, setNote] = useState("");

  return (
    <View style={styles.container}>
      <View style={styles.bodyWrap}>
        {tab === "Сагс" ? (
          <Text nativeID="sbody" style={styles.h}>Сагс</Text>
        ) : (
          <View style={styles.pad}>
            <Text style={styles.h}>Профайл</Text>
            <TextInput nativeID="note" style={styles.input} placeholder="Тэмдэглэл"
              value={note} onChangeText={setNote} />
          </View>
        )}
      </View>
      <View style={styles.tabbar}>
        {["Нүүр", "Сагс", "Профайл"].map((t, i) => (
          <Pressable key={t} nativeID={"tab" + i} style={styles.tab} onPress={() => setTab(t)}>
            <Text style={styles.tabText}>{t}</Text>
          </Pressable>
        ))}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  bodyWrap: { flex: 1 },
  pad: { flex: 1, padding: 24, gap: 14, justifyContent: "center" },
  h: { fontSize: 20, fontWeight: "bold" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 12 },
  tabbar: { flexDirection: "row", borderTopWidth: 1, borderTopColor: "#e5e7eb" },
  tab: { flexGrow: 1, paddingVertical: 12, alignItems: "center" },
  tabText: { fontWeight: "600", color: "#334155" },
});

registerRootComponent(App);
